QUERY_LIST_PROJECT_ITEMS:
query ($projectId: ID!, $cursor: String) {
  node(id: $projectId) {
    ... on ProjectV2 {
      items(first: 100, after: $cursor) {
        nodes {
          id
          updatedAt
          fieldValues(first: 10) {
            nodes {
              ... on ProjectV2ItemFieldSingleSelectValue {
                field {
                  ... on ProjectV2SingleSelectField {
                    name
                  }
                }
                name
              }
            }
          }
          content {
            ... on Issue {
              id
              number
              title
              state
              url
              issueType {
                name
              }
              subIssues(first: 1) {
                totalCount
              }
              parent {
                number
                repository {
                  owner {
                    login
                  }
                  name
                }
              }
              issueDependenciesSummary {
                totalBlockedBy
              }
              labels(first: 10) {
                nodes {
                  name
                }
              }
              repository {
                owner {
                  login
                }
                name
              }
            }
            ... on PullRequest {
              id
              number
              title
              state
              url
              repository {
                owner {
                  login
                }
                name
              }
            }
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  }
}

