QUERY_GET_ISSUE_SLIM:
query ($owner: String!, $repo: String!, $number: Int!, $commentLimit: Int!) {
  repository(owner: $owner, name: $repo) {
    issue(number: $number) {
      number
      state
      title
      body
      comments(last: $commentLimit) {
        totalCount
        nodes {
          author {
            login
          }
          createdAt
          body
        }
      }
      parent {
        number
        title
        state
        repository {
          owner {
            login
          }
          name
        }
      }
      subIssues(first: 20) {
        nodes {
          number
          state
          title
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
      linkedBranches(first: 10) {
        nodes {
          ref {
            name
          }
        }
      }
      timelineItems(itemTypes: [CONNECTED_EVENT, CROSS_REFERENCED_EVENT], first: 20) {
        nodes {
          ... on ConnectedEvent {
            subject {
              ... on PullRequest {
                number
                title
                state
              }
            }
          }
          ... on CrossReferencedEvent {
            source {
              ... on PullRequest {
                number
                title
                state
              }
            }
          }
        }
      }
    }
  }
}

