QUERY_LIST_OPEN_PULL_REQUESTS:
query ($owner: String!, $repo: String!, $after: String) {
  repository(owner: $owner, name: $repo) {
    pullRequests(
      first: 25
      states: OPEN
      after: $after
      orderBy: { field: CREATED_AT, direction: ASC }
    ) {
      pageInfo {
        hasNextPage
        endCursor
      }
      nodes {
        number
        title
        url
        createdAt
        author {
          __typename
          login
        }
        isInMergeQueue
        autoMergeRequest {
          enabledAt
        }
        mergeable
        baseRef {
          target {
            ... on Commit {
              committedDate
            }
          }
        }
        firstCommits: commits(first: 1) {
          nodes {
            commit {
              message
              signature {
                isValid
              }
              author {
                user {
                  login
                }
              }
            }
          }
        }
        headCommits: commits(last: 1) {
          nodes {
            commit {
              statusCheckRollup {
                state
              }
            }
          }
        }
        lastForcePush: timelineItems(last: 1, itemTypes: [HEAD_REF_FORCE_PUSHED_EVENT]) {
          nodes {
            ... on HeadRefForcePushedEvent {
              createdAt
            }
          }
        }
        lastDequeue: timelineItems(last: 1, itemTypes: [REMOVED_FROM_MERGE_QUEUE_EVENT]) {
          nodes {
            ... on RemovedFromMergeQueueEvent {
              createdAt
            }
          }
        }
      }
    }
  }
}
